def extract_quotation(s):
    result = []
    i = 0
    while i < len(s):
        if s[i] == '"':
            j = i + 1
            while j < len(s) and s[j] != '"':
                j += 1
            if j < len(s):
                result.append(s[i+1:j])
                i = j + 1
            else:
                break
        else:
            i += 1
    return result
